                regionCommentAnchorY: mark.regionCommentAnchorY !== null && mark.regionCommentAnchorY !== '' && Number.isFinite(Number(mark.regionCommentAnchorY)) ? Math.max(0, Math.min(100, Number(mark.regionCommentAnchorY))) : null,
