            if ((requestedLayer === 'all' || requestedLayer === 'inner') && style.innerOutline) {
                drawLayer(style.innerColor, armStrokeWidth + style.innerWidth * 2);
            }
            if (requestedLayer === 'all' || requestedLayer === 'main') {
                drawLayer(style.color, armStrokeWidth);
            }
            ctx.restore();
